// Map a Unicode codepoint to a glyph index, or -1 if not covered.
static inline int fontGlyphIndex(uint32_t cp) {
  if (cp >= 0x20 && cp <= 0x7E)    return (int)(cp - 0x20);
  if (cp >= 0x5D0 && cp <= 0x5EA)  return 95 + (int)(cp - 0x5D0);
  if (cp == 0x5F3) return 122;  // geresh
  if (cp == 0x5F4) return 123;  // gershayim
  return -1;
}
